import pickle
import time
from typing import Any, Optional

class SessionCache:
    def __init__(self, max_size: int = 10000):
        self.cache = {}
        self.max_size = max_size
        self.access_times = {}

    def get(self, session_id: str) -> Optional[dict]:
        if session_id in self.cache:
            self.access_times[session_id] = time.time()
            # Deserialize from pickle
            return pickle.loads(self.cache[session_id])
        return None

    def set(self, session_id: str, session_data: dict) -> None:
        if len(self.cache) >= self.max_size:
            # Evict least recently used
            lru_id = min(self.access_times, key=self.access_times.get)
            del self.cache[lru_id]
            del self.access_times[lru_id]

        # Serialize to pickle for fast storage
        self.cache[session_id] = pickle.dumps(session_data)
        self.access_times[session_id] = time.time()

    def delete(self, session_id: str) -> None:
        self.cache.pop(session_id, None)
        self.access_times.pop(session_id, None)
